head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gIDX_MKT_CLSS_ID = "";
scwin.gIDX_ASST_CLSS_ID = "";
scwin.gIDX_MKT_CLSS_ID_L = "";
scwin.gIDX_MKT_CLSS_ID_M = "";
scwin.gIDX_ASST_CLSS_ID_L = "";
scwin.gIDX_ASST_CLSS_ID_M = "";

// var vCurDate = cGetToday("yyyymmdd");    // 오늘날짜

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92040.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    await scwin.searchCode();
    await scwin.searchCombo();
    await scwin.listSync();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_MKT_TP_CD_L_onviewchange
 * @description 기초시장구분(대) onviewChange
 * @returns {void}
 * @hidden N
 */
scwin.cmb_MKT_TP_CD_L_onviewchange = function() {
    try {
        scwin.gIDX_MKT_CLSS_ID_L = cmb_MKT_TP_CD_L.getValue();

        if($c.util.isEmpty(scwin.gIDX_MKT_CLSS_ID_L)){
            dlt_MKT_TP_CD_M.removeColumnFilterAll();
            dlt_MKT_TP_CD_S.removeColumnFilterAll();
            return;
        }

        // 기초시장구분(중) filter
        dlt_MKT_TP_CD_M.removeColumnFilterAll();
        dlt_MKT_TP_CD_S.removeColumnFilterAll();
        dlt_MKT_TP_CD_M.setColumnFilter({type:"row", colIndex:"upMktClssId", key: scwin.gIDX_MKT_CLSS_ID_L, condition:"and", exactMatch:true})
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92040.cmb_MKT_TP_CD_L_onviewchange" });
    }
};

/**
 * @method
 * @name cmb_MKT_TP_CD_M_onviewchange
 * @description 기초시장구분(중) onviewChange
 * @returns {void}
 * @hidden N
 */
scwin.cmb_MKT_TP_CD_M_onviewchange = function() {
    try {
        scwin.gIDX_MKT_CLSS_ID_M = cmb_MKT_TP_CD_M.getValue();

        if($c.util.isEmpty(scwin.gIDX_MKT_CLSS_ID_M)){
            // 기초시장구분(중) filter
            dlt_MKT_TP_CD_S.removeColumnFilterAll();
            return;
        }

        // 기초시장구분(소) filter
        dlt_MKT_TP_CD_S.removeColumnFilterAll();
        dlt_MKT_TP_CD_S.setColumnFilter({type:"row", colIndex:"upMktClssId", key: scwin.gIDX_MKT_CLSS_ID_M, condition:"and", exactMatch:true})
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92040.cmb_MKT_TP_CD_M_onviewchange" });
    }
};

/**
 * @method
 * @name cmb_ULY_TP_CD_L_onviewchange
 * @description 기초자산 구분(대) onviewcng
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ULY_TP_CD_L_onviewchange = function() {
    try {
        scwin.gIDX_ASST_CLSS_ID_L = cmb_ULY_TP_CD_L.getValue();

        if($c.util.isEmpty(scwin.gIDX_ASST_CLSS_ID_L)){
            dlt_ULY_TP_CD_M.removeColumnFilterAll();
            dlt_ULY_TP_CD_S.removeColumnFilterAll();
            return;
        }

        // 기초자산 구분(중) filter
        dlt_ULY_TP_CD_M.removeColumnFilterAll();
        dlt_ULY_TP_CD_S.removeColumnFilterAll();
        dlt_ULY_TP_CD_M.setColumnFilter({type:"row", colIndex:"upAsstClssId", key: scwin.gIDX_ASST_CLSS_ID_L, condition:"and", exactMatch:true})

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92040.cmb_ULY_TP_CD_L_onviewchange" });
    }
};

/**
 * @method
 * @name cmb_ULY_TP_CD_M_onviewchange
 * @description 기초자산 구분(중) onviewcng
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ULY_TP_CD_M_onviewchange = function() {
    try {
        scwin.gIDX_ASST_CLSS_ID_M = cmb_ULY_TP_CD_M.getValue();

        if($c.util.isEmpty(scwin.gIDX_ASST_CLSS_ID_M)){
            // 기초시장구분(중) filter
            dlt_ULY_TP_CD_S.removeColumnFilterAll();
            return;
        }

        // 기초시장구분(소) filter
        dlt_ULY_TP_CD_S.removeColumnFilterAll();
        dlt_ULY_TP_CD_S.setColumnFilter({type:"row", colIndex:"upAsstClssId", key: scwin.gIDX_ASST_CLSS_ID_M, condition:"and", exactMatch:true})
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92040.cmb_ULY_TP_CD_M_onviewchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 조회버튼 clck
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92040.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_select_onclick
 * @description 「선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_select_onclick = async function() {
    try {
        await scwin.setParBasIdxInfo();
        // fn_ExcelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92040.btn_select_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92040.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_SRH_IDX_NM_onkeyup
 * @description txb_SRH_IDX_NM 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txb_SRH_IDX_NM_onkeyup = async function (e) {
    try {
        if (e.keyCode === 13 || e.key === "Enter") {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92040.txb_SRH_IDX_NM_onkeyup" });
    }
};

/**
 * @method
 * @name grd_List_oncelldblclick
 * @description grd_List 셀 더블클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.setParBasIdxInfo(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92040.grd_List_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCombo
 * @description 기초시장·기초자산 콤보 조회(대/중분류)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCombo = async function() {
    /* 기초시장 대분류 */
    let sbmOptions = {
        id : "sbm_listLeadcomAll",
        method: "get",
        action : "/api/listing/common/code/underlying-asset-code",
        target : "dlt_MKT_TP_CD_L=body",
        isProcessMsg : false
    };
    await $c.sbm.executeDynamic(sbmOptions, {'levelTpCd' : 'L'});

    /* 기초시장 중분류 */
    sbmOptions.target = "dlt_MKT_TP_CD_M=body";
    await $c.sbm.executeDynamic(sbmOptions, {'levelTpCd' : 'M'});

    /* 기초시장 소분류 */
    sbmOptions.target = "dlt_MKT_TP_CD_S=body";
    await $c.sbm.executeDynamic(sbmOptions, {'levelTpCd' : 'S'});

    ///////////////////////////////////////////////////////////////////////////////////

    /* 기초자산 대분류 */
    sbmOptions.action = "/api/listing/common/code/base-market-code";
    sbmOptions.target = "dlt_ULY_TP_CD_L=body";
    await $c.sbm.executeDynamic(sbmOptions, {'levelTpCd' : 'L'});

    /* 기초자산 중분류 */
    sbmOptions.target = "dlt_ULY_TP_CD_M=body";
    await $c.sbm.executeDynamic(sbmOptions, {'levelTpCd' : 'M'});

    /* 기초자산 소분류 */
    sbmOptions.target = "dlt_ULY_TP_CD_S=body";
    await $c.sbm.executeDynamic(sbmOptions, {'levelTpCd' : 'S'});
};

/**
 * @method
 * @name listSync
 * @description 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    // 기초시장 대/중/소 미선택시
    if ($c.util.isEmpty(cmb_MKT_TP_CD_L.getValue()) && $c.util.isEmpty(cmb_MKT_TP_CD_M.getValue()) && $c.util.isEmpty(cmb_MKT_TP_CD_S.getValue()) ) {
        scwin.gIDX_MKT_CLSS_ID = "______";
    }

    // 기초시장 대분류만 선택시
    if (!$c.util.isEmpty(cmb_MKT_TP_CD_L.getValue()) && $c.util.isEmpty(cmb_MKT_TP_CD_M.getValue()) && $c.util.isEmpty(cmb_MKT_TP_CD_S.getValue()) ) {
        scwin.gIDX_MKT_CLSS_ID = cmb_MKT_TP_CD_L.getValue().substr(0, 2) + "____";
    }

    // 기초시장 대분류 미선택
    //               중분류만 선택시
    if ($c.util.isEmpty(cmb_MKT_TP_CD_L.getValue()) && !$c.util.isEmpty(cmb_MKT_TP_CD_M.getValue()) && $c.util.isEmpty(cmb_MKT_TP_CD_S.getValue()) ) {
        scwin.gIDX_MKT_CLSS_ID = cmb_MKT_TP_CD_M.getValue().substr(0, 4) + "__";
    }

    // 기초시장 대분류 미선택
    //               중분류 미선택
    //               소분류만 선택시
    if ($c.util.isEmpty(cmb_MKT_TP_CD_L.getValue()) && $c.util.isEmpty(cmb_MKT_TP_CD_M.getValue()) && !$c.util.isEmpty(cmb_MKT_TP_CD_S.getValue()) ) {
        scwin.gIDX_MKT_CLSS_ID = cmb_MKT_TP_CD_S.getValue();
    }

    // 기초시장 대분류 선택
    //               중분류 선택
    //            소분류 미선택시
    if (!$c.util.isEmpty(cmb_MKT_TP_CD_L.getValue()) && !$c.util.isEmpty(cmb_MKT_TP_CD_M.getValue()) && $c.util.isEmpty(cmb_MKT_TP_CD_S.getValue()) ) {
        scwin.gIDX_MKT_CLSS_ID = cmb_MKT_TP_CD_M.getValue().substr(0, 4) + "__";
    }

    // 기초시장 대분류 미선택
    //               중분류 선택시
    //               소분류 선택시
    if ($c.util.isEmpty(cmb_MKT_TP_CD_L.getValue()) && !$c.util.isEmpty(cmb_MKT_TP_CD_M.getValue()) && !$c.util.isEmpty(cmb_MKT_TP_CD_S.getValue()) ) {
        scwin.gIDX_MKT_CLSS_ID = cmb_MKT_TP_CD_S.getValue();
    }

    // 기초시장 대분류 선택시
    //               중분류 선택시
    //               소분류 선택시
    if (!$c.util.isEmpty(cmb_MKT_TP_CD_L.getValue()) && !$c.util.isEmpty(cmb_MKT_TP_CD_M.getValue()) && !$c.util.isEmpty(cmb_MKT_TP_CD_S.getValue())) {
        scwin.gIDX_MKT_CLSS_ID = cmb_MKT_TP_CD_S.getValue();
    }

    ///////////////////////////////////////////////////////////////////////////////////////////////////////////

    // 기초자산 대/중/소 미선택시
    if ($c.util.isEmpty(cmb_ULY_TP_CD_L.getValue()) && $c.util.isEmpty(cmb_ULY_TP_CD_M.getValue()) && $c.util.isEmpty(cmb_ULY_TP_CD_S.getValue()) ) {
        scwin.gIDX_ASST_CLSS_ID = "______";
    }

    // 기초자산 대분류만 선택시
    if (!$c.util.isEmpty(cmb_ULY_TP_CD_L.getValue()) && $c.util.isEmpty(cmb_ULY_TP_CD_M.getValue()) && $c.util.isEmpty(cmb_ULY_TP_CD_S.getValue()) ) {
        scwin.gIDX_ASST_CLSS_ID = cmb_ULY_TP_CD_L.getValue().substr(0, 2) + "____";
    }

    // 기초자산 대분류 미선택
    //               중분류만 선택시
    if ($c.util.isEmpty(cmb_ULY_TP_CD_L.getValue()) && !$c.util.isEmpty(cmb_ULY_TP_CD_M.getValue()) && $c.util.isEmpty(cmb_ULY_TP_CD_S.getValue()) ) {
        scwin.gIDX_ASST_CLSS_ID = cmb_ULY_TP_CD_M.getValue().substr(0, 4) + "__";
    }

    // 기초자산 대분류 미선택
    //               중분류 미선택
    //               소분류만 선택시
    if ($c.util.isEmpty(cmb_ULY_TP_CD_L.getValue()) && $c.util.isEmpty(cmb_ULY_TP_CD_M.getValue()) && !$c.util.isEmpty(cmb_ULY_TP_CD_S.getValue()) ) {
        scwin.gIDX_ASST_CLSS_ID = cmb_ULY_TP_CD_S.getValue();
    }

    // 기초자산 대분류 선택
    //               중분류 선택
    //            소분류 미선택시
    if (!$c.util.isEmpty(cmb_ULY_TP_CD_L.getValue()) && !$c.util.isEmpty(cmb_ULY_TP_CD_M.getValue()) && $c.util.isEmpty(cmb_ULY_TP_CD_S.getValue()) ){
        scwin.gIDX_ASST_CLSS_ID = cmb_ULY_TP_CD_M.getValue().substr(0, 4) + "__";
    }

    // 기초자산 대분류 미선택
    //               중분류 선택시
    //               소분류 선택시
    if ($c.util.isEmpty(cmb_ULY_TP_CD_L.getValue()) && !$c.util.isEmpty(cmb_ULY_TP_CD_M.getValue()) && !$c.util.isEmpty(cmb_ULY_TP_CD_S.getValue()) ) {
        scwin.gIDX_ASST_CLSS_ID = cmb_ULY_TP_CD_S.getValue();
    }

    // 기초자산 대분류 선택시
    //               중분류 선택시
    //               소분류 선택시
    if (!$c.util.isEmpty(cmb_ULY_TP_CD_L.getValue()) && !$c.util.isEmpty(cmb_ULY_TP_CD_M.getValue()) && !$c.util.isEmpty(cmb_ULY_TP_CD_S.getValue()) ) {
        scwin.gIDX_ASST_CLSS_ID = cmb_ULY_TP_CD_S.getValue();
    }

    dlt_list.removeAll();
    dma_search.set("idxMktClssId", scwin.gIDX_MKT_CLSS_ID);// 기초시장ID
    dma_search.set("idxAsstClssId", scwin.gIDX_ASST_CLSS_ID);// 기초자산ID

    const sbmOptions = {
        id : "sbm_listLeadcomAll",
        method: "get",
        ref : "dma_search",
        action : "/api/listing/lstproc/etf/newlisting/management/base-idx/select-list",
        target : "dlt_list=body",
        isProcessMsg : false
    };
    const rslt = await $c.sbm.executeDynamic(sbmOptions);
    if (!rslt || rslt.skipped) {
        return;
    }
    if (rslt.responseJSON.success) {
        panel_page.setValue(dlt_list.getRowCount());
    }

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchCode
 * @description 공통코드 조회(콤보 항목 구성)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    03905  지수산출기관코드
    03902  지수레버리지인버스구분코드
     */

    // 공통코드 설정
    const codeOptions = [
        {
            code: "IDX_CALC_INST_CD",
            compID: "cmb_IDX_CALC_INST_CD",
            firstRow : ["", "전체"]
        },
        {
            code: "IDX_LVRG_INVRS_TP_CD",
            firstRow : ["", "전체"],
            compID: "cmb_IDX_LVRG_INVRS_TP_CD"
        }
    ];

    await $c.data.setCommonCode(codeOptions);
};

/**
 * @method
 * @name setParBasIdxInfo
 * @description 선택 지수정보를 셋팅해준다
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParBasIdxInfo = async function(row) {
    if (row === undefined || row === null) {
        row = dlt_list.getRowPosition();
    }
    $c.win.closePopup(dlt_list.getRowJSON(row));
};
